window.BOOK={"key":"bustiyya","app":"mutoon-bustiyya","lsk":"mutoon_bustiyya_v1","prefix":"bu_","title":"نونية البستي","sub":"الشعر العربي · أبو الفتح البستي (ت ٤٠٠هـ) · ٦٣ بيتًا","poems":[{"id":"bustiyya","title":"نونية البستي","nazim":"أبو الفتح علي بن محمد البستي","death":"ت ٤٠٠هـ","meter":"البسيط","source":"المكتبة الشاملة: قصيدة عنوان الحكم، تحقيق عبد الفتاح أبو غدة (مكتب المطبوعات الإسلامية، ١٤٠٤هـ)","srcUrl":"https://ketabonline.com/ar/books/5412","note":"نص «عنوان الحكم» بتحقيق أبي غدة (٦٣ بيتًا)، قوبل كلمةً كلمةً بسكربت بطبعة أبي غدة المشكولة المفردة وبنص ويكي مصدر. النص مشكول جزئيًا (نحو ٦٣٪ من الحروف): أُكمل الشكل من نشرة أبي غدة المشكولة، وصُحّح ما كسر الوزن من نصّ ويكي مصدر، والتفصيل في تقرير المصادر. وأكمل الذكاء الاصطناعي شكل ما لم يُشكل على الوزن، ويحسن مراجعته.","verses":[["زِيَادَةُ الْمَرْءِ فِي دُنْيَاهُ نُقْصَانُ","وَرِبْحُهُ غَيْرَ مَحْضِ الْخَيْرِ خُسْرَانُ"],["وَكُلُّ وِجْدَانِ حَظٍّ لَا ثَبَاتَ لَهُ","فَإِنَّ مَعْنَاهُ فِي التَّحْقِيقِ فِقْدَانُ"],["يَا عَامِرًا لِخَرَابِ الدَّارِ مُجْتَهِدًا","بِاللَّهِ هَلْ لِخَرَابِ الْعُمْرِ عُمْرَانُ"],["وَيَا حَرِيصًا عَلَى الْأَمْوَالِ تَجْمَعُهَا","أُنْسِيتَ أَنَّ سُرُورَ الْمَالِ أَحْزَانُ"],["زَعِ الْفُؤَادَ عَنِ الدُّنْيَا وَزِينَتِهَا","فَصَفْوُهَا كَدَرٌ وَالْوَصْلُ هِجْرَانُ"],["وَأَرْعِ سَمْعَكَ أَمْثَالًا أُفَصِّلُهَا","كَمَا يُفَصَّلُ يَاقُوتٌ وَمَرْجَانُ"],["أَحْسِنْ إِلَى النَّاسِ تَسْتَعْبِدْ قُلُوبَهُمُ","فَطَالَمَا اسْتَعْبَدَ الْإِنْسَانَ إِحْسَانُ"],["يَا خَادِمَ الْجِسْمِ كَمْ تَشْقَى بِخِدْمَتِهِ","أَتَطْلُبُ الرِّبْحَ فِيمَا فِيهِ خُسْرَانُ"],["أَقْبِلْ عَلَى النَّفْسِ وَاسْتَكْمِلْ فَضَائِلَهَا","فَأَنْتَ بِالنَّفْسِ لَا بِالْجِسْمِ إِنْسَانُ"],["وَإِنْ أَسَاءَ مُسِيءٌ فَلْيَكُنْ لَكَ فِي","عُرُوضِ زَلَّتِهِ صَفْحٌ وَغُفْرَانُ"],["وَكُنْ عَلَى الدَّهْرِ مِعْوَانًا لِذِى أَمَلٍ","يَرْجُو نَدَاكَ فَإِنَّ الْحُرَّ مِعْوَانُ"],["وَاشْدُدْ يَدَيْكَ بِحَبْلِ اللَّهِ مُعْتَصِمًا","فَإِنَّهُ الرُّكْنُ إِنْ خَانَتْكَ أَرْكَانُ"],["مَنْ يَتَّقِ اللَّهَ يُحْمَدْ فِي عَوَاقِبِهِ","وَيَكْفِهِ شَرَّ مَنْ عَزُّوا وَمَنْ هَانُوا"],["مَنِ اسْتَعَانَ بِغَيْرِ اللَّهِ فِي طَلَبٍ","فَإِنَّ نَاصِرَهُ عَجْزٌ وَخِذْلَانُ"],["مَنْ كَانَ لِلْخَيْرِ مَنَّاعًا فَلَيْسَ لَهُ","عَلَى الْحَقِيقَةِ إِخْوَانٌ وَأَخْدَانُ"],["مَنْ جَادَ بِالْمَالِ مَالَ النَّاسُ قَاطِبَةً","إِلَيْهِ وَالْمَالُ لِلْإِنْسَانِ فَتَّانُ"],["مَنْ سَالَمَ النَّاسَ يَسْلَمْ مِنْ غَوَائِلِهِمْ","وَعَاشَ وَهْوَ قَرِيرُ الْعَيْنِ جَذْلَانُ"],["مَنْ كَانَ لِلْعَقْلِ سُلْطَانٌ عَلَيْهِ غَدَا","وَمَا عَلَى نَفْسِهِ لِلْحِرْصِ سُلْطَانُ"],["مَنْ مَدَّ طَرْفًا لِفَرْطِ الْجَهْلِ نَحْوَ هَوًى","أَغْضَى عَلَى الْحَقِّ يَوْمًا وَهْوَ خَزْيَانُ"],["مَنْ عَاشَرَ النَّاسَ لَاقَى مِنْهُمُ نَصَبًا","لِأَنَّ سُوسَهُمُ بَغْيٌ وَعُدْوَانُ"],["وَمَنْ يُفَتِّشْ عَنِ الْإِخْوَانِ يَقْلِهِمُ","فَجُلُّ إِخْوَانِ هَذَا الْعَصْرِ خَوَّانُ"],["مَنِ اسْتَشَارَ صُرُوفَ الدَّهْرِ قَامَ لَهُ","عَلَى حَقِيقَةِ طَبْعِ الدَّهْرِ بُرْهَانُ"],["مَنْ يَزْرَعِ الشَّرَّ يَحْصُدْ فِي عَوَاقِبِهِ","نَدَامَةً وَلِحَصْدِ الزَّرْعِ إِبَّانُ"],["مَنِ اسْتَنَامَ إِلَى الْأَشْرَارِ نَامَ وَفِي","قَمِيصِهِ مِنْهُمُ صِلٌّ وَثُعْبَانُ"],["كُنْ رَيِّقَ الْبِشْرِ إِنَّ الْحُرَّ هِمَّتُهُ","صَحِيفَةٌ وَعَلَيْهَا الْبِشْرُ عُنْوَانُ"],["وَرَافِقِ الرِّفْقَ فِي كُلِّ الْأُمُورِ فَلَمْ","يَنْدَمْ رَفِيقٌ وَلَمْ يَذْمُمْهُ إِنْسَانُ"],["وَلَا يَغُرَّنْكَ حَظٌّ جَرَّهُ خَرَقٌ","فَالْخُرْقُ هَدْمٌ وَرِفْقُ الْمَرْءِ بُنْيَانُ"],["أَحْسِنْ إِذَا كَانَ إِمْكَانٌ وَمَقْدِرَةٌ","فَلَنْ يَدُومَ عَلَى الْإِحْسَانِ إِمْكَانُ"],["فَالرَّوْضُ يَزْدَانُ بِالْأَنْوَارِ فَاغِمَةً","وَالْحُرُّ بِالْعَدْلِ وَالْإِحْسَانِ يَزْدَانُ"],["صُنْ حُرَّ وَجْهِكَ لَا تَهْتِكْ غِلَالَتَهُ","فَكُلُّ حُرٍّ لِحُرِّ الْوَجْهِ صَوَّانُ"],["فَإِنْ لَقِيتَ عَدُوًّا فَالْقَهُ أَبَدًا","وَالْوَجْهُ بِالْبِشْرِ وَالْإِشْرَاقِ غَضَّانُ"],["دَعِ التَّكَاسُلَ فِي الْخَيْرَاتِ تَطْلُبُهَا","فَلَيْسَ يَسْعَدُ بِالْخَيْرَاتِ كَسْلَانُ"],["لَا ظِلَّ لِلْمَرْءِ يَعْرَى مِنْ تُقًى وَنُهًى","وَإِنْ أَظَلَّتْهُ أَوْرَاقٌ وَأَفْنَانُ"],["وَالنَّاسُ أَعْوَانُ مَنْ وَالَتْهُ دَوْلَتُهُ","وَهُمْ عَلَيْهِ إِذَا عَادَتْهُ أَعْوَانُ"],["سَحْبَانُ مِنْ غَيْرِ مَالٍ بَاقِلٌ حَصِرٌ","وَبَاقِلٌ فِي ثَرَاءِ الْمَالِ سَحْبَانُ"],["لَا تُودِعِ السِّرَّ وَشَّاءً يَبُوحُ بِهِ","فَمَا رَعَى غَنَمًا فِي الدَّوِّ سِرْحَانُ"],["لَا تَحْسَبِ النَّاسَ طَبْعًا وَاحِدًا فَلَهُمْ","غَرَائِزٌ لَسْتَ تُحْصِيهِنَّ أَلْوَانُ"],["مَا كُلُّ مَاءٍ كَصَدَّاءٍ لِوَارِدِهِ","نَعَمْ وَلَا كُلُّ نَبْتٍ فَهْوَ سَعْدَانُ"],["لَا تَخْدِشَنَّ بِمَطْلٍ وَجْهَ عَارِفَةٍ","فَالْبِرُّ يَخْدِشُهُ مَطْلٌ وَلَيَّانُ"],["لَا تَسْتَشِرْ غَيْرَ نَدْبٍ حَازِمٍ يَقِظٍ","قَدِ اسْتَوَى فِيهِ إِسْرَارٌ وَإِعْلَانُ"],["فَلِلتَّدَابِيرِ فُرْسَانٌ إِذَا رَكَضُوا","فِيهَا أَبَرُّوا كَمَا لِلْحَرْبِ فُرْسَانُ"],["وَلِلْأُمُورِ مَوَاقِيتٌ مُقَدَّرَةٌ","وَكُلُّ أَمْرٍ لَهُ حَدٌّ وَمِيزَانُ"],["فَلَا تَكُنْ عَجِلًا بِالْأَمْرِ تَطْلُبُهُ","فَلَيْسَ يُحْمَدُ قَبْلَ النُّضْجِ بُحْرَانُ"],["كَفَى مِنَ الْعَيْشِ مَا قَدْ سَدَّ مِنْ عَوَزٍ","فَفِيهِ لِلْحُرِّ إِنْ حَقَّقْتَ غُنْيَانُ"],["وَذُو الْقَنَاعَةِ رَاضٍ مِنْ مَعِيشَتِهِ","وَصَاحِبُ الْحِرْصِ إِنْ أَثْرَى فَغَضْبَانُ"],["حَسْبُ الْفَتَى عَقْلُهُ خِلًّا يُعَاشِرُهُ","إِذَا تَحَامَاهُ إِخْوَانٌ وَخُلَّانُ"],["هُمَا رَضِيعَا لِبَانٍ حِكْمَةٌ وَتُقًى","وَسَاكِنَا وَطَنٍ مَالٌ وَطُغْيَانُ"],["إِذَا نَبَا بِكَرِيمٍ مَوْطِنٌ فَلَهُ","وَرَاءَهُ فِي بَسِيطِ الْأَرْضِ أَوْطَانُ"],["يَا ظَالِمًا فَرِحًا بِالْعِزِّ سَاعَدَهُ","إِنْ كُنْتَ فِي سِنَةٍ فَالدَّهْرُ يَقْظَانُ"],["مَا اسْتَمْرَأَ الظُّلْمَ لَوْ أَنْصَفْتَ آكِلُهُ","وَهَلْ يَلَذُّ مَذَاقَ الْمَرْءِ خُطْبَانُ"],["يَا أَيُّهَا الْعَالِمُ الْمَرْضِيُّ سِيرَتُهُ","أَبْشِرْ فَأَنْتَ بِغَيْرِ الْمَاءِ رَيَّانُ"],["وَيَا أَخَا الْجَهْلِ لَوْ أَصْبَحْتَ فِي لُجَجٍ","فَأَنْتَ مَا بَيْنَهَا لَا شَكَّ ظَمْآنُ"],["لَا تَحْسَبَنَّ سُرُورًا دَائِمًا أَبَدًا","مَنْ سَرَّهُ زَمَنٌ سَاءَتْهُ أَزْمَانُ"],["إِذَا جَفَاكَ خَلِيلٌ كُنْتَ تَأْلَفُهُ","فَاطْلُبْ سِوَاهُ فَكُلُّ النَّاسِ إِخْوَانُ"],["وَإِنْ نَبَتْ بِكَ أَوْطَانٌ نَشَأْتَ بِهَا","فَارْحَلْ فَكُلُّ بِلَادِ اللَّهِ أَوْطَانُ"],["يَا رَافِلًا فِي الشَّبَابِ الرَّحْبِ مُنْتَشِيًا","مِنْ كَأْسِهِ هَلْ أَصَابَ الرُّشْدَ نَشْوَانُ"],["لَا تَغْتَرِرْ بِشَبَابٍ رَائِقٍ نَضِرٍ","فَكَمْ تَقَدَّمَ قَبْلَ الشَّيْبِ شُبَّانُ"],["وَيَا أَخَا الشَّيْبِ لَوْ نَاصَحْتَ نَفْسَكَ لَمْ","يَكُنْ لِمِثْلِكَ فِي اللَّذَّاتِ إِمْعَانُ"],["هَبِ الشَّبِيبَةَ تُبْدِي عُذْرَ صَاحِبِهَا","مَا عُذْرُ أَشْيَبَ يَسْتَهْوِيهِ شَيْطَانُ"],["كُلُّ الذُّنُوبِ فَإِنَّ اللَّهَ يَغْفِرُهَا","إِنْ شَيَّعَ الْمَرْءَ إِخْلَاصٌ وَإِيمَانُ"],["وَكُلُّ كَسْرٍ فَإِنَّ الدِّينَ يَجْبُرُهُ","وَمَا لِكَسْرِ قَنَاةِ الدِّينِ جُبْرَانُ"],["خُذْهَا سَوَائِرَ أَمْثَالٍ مُهَذَّبَةً","فِيهَا لِمَنْ يَبْتَغِي التِّبْيَانَ تِبْيَانُ"],["مَا ضَرَّ حَسَّانَهَا وَالطَّبْعُ صَائِغُهَا","أَنْ لَمْ يَصُغْهَا قَرِيعُ الشِّعْرِ حَسَّانُ"]],"secs":{"1":"نُونِيَّةُ الْبُسْتِيِّ"}}],"sharh":false};
